```rust
use std::sync::atomic::{AtomicI32, Ordering};
use std::sync::Arc;
use std::thread;

fn w1(c: Arc<AtomicI32>) {
    loop {
        let expected = c.load(Ordering::SeqCst);
        let desired = expected + 1;
        let old = match c.compare_exchange(expected, desired, Ordering::SeqCst, Ordering::SeqCst) {
            Ok(old) | Err(old) => old,
        };
        if old == expected {
            return;
        }
    }
}

fn w2(c: Arc<AtomicI32>) {
    loop {
        let expected = c.load(Ordering::SeqCst);
        let desired = expected + 1;
        let old = match c.compare_exchange(expected, desired, Ordering::SeqCst, Ordering::SeqCst) {
            Ok(old) | Err(old) => old,
        };
        if old == expected {
            return;
        }
    }
}

fn main() {
    let c = Arc::new(AtomicI32::new(0));

    let c1 = Arc::clone(&c);
    let c2 = Arc::clone(&c);
    let t1 = thread::spawn(move || w1(c1));
    let t2 = thread::spawn(move || w2(c2));

    t1.join().unwrap();
    t2.join().unwrap();

    let done = i32::from(c.load(Ordering::SeqCst) == 2);
    println!("DONE done={done}");
}
```

```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct State {
    ready: bool,
}

fn waiter(m: Arc<Mutex<State>>, cv: Arc<Condvar>) {
    let mut state = m.lock().unwrap();

    while !state.ready {
        state = cv.wait(state).unwrap();
    }
}

fn notifier(m: Arc<Mutex<State>>, cv: Arc<Condvar>) {
    let mut state = m.lock().unwrap();
    state.ready = true;
    cv.notify_one();
    drop(state);
}

fn main() {
    let m = Arc::new(Mutex::new(State { ready: false }));
    let cv = Arc::new(Condvar::new());

    let waiter_m = Arc::clone(&m);
    let waiter_cv = Arc::clone(&cv);
    let waiter_handle = thread::spawn(move || waiter(waiter_m, waiter_cv));

    let notifier_m = Arc::clone(&m);
    let notifier_cv = Arc::clone(&cv);
    let notifier_handle = thread::spawn(move || notifier(notifier_m, notifier_cv));

    waiter_handle.join().unwrap();
    notifier_handle.join().unwrap();

    let state = m.lock().unwrap();
    println!("DONE ready={}", state.ready);
}
```

