use std::hint::black_box;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct State {
    permits: usize,
    next_ticket: u64,
    serving_ticket: u64,
}

struct Semaphore {
    state: Mutex<State>,
    changed: Condvar,
}

impl Semaphore {
    fn new(permits: usize) -> Self {
        Self {
            state: Mutex::new(State {
                permits,
                next_ticket: 0,
                serving_ticket: 0,
            }),
            changed: Condvar::new(),
        }
    }

    fn acquire(&self) -> Permit<'_> {
